window.COUNTRY_GUIDES = [
 { code:"BE", links:[["Affaires étrangères (Belges à l'étranger)","https://diplomatie.belgium.be/"],["Service fédéral des Pensions","https://www.sfpd.fgov.be/"]],
   p:tr([
    ["Déclarez votre départ à votre commune avant de partir : vous recevez un certificat de changement de résidence (modèle 8).","Pensionnés : demandez le formulaire S1 à votre mutualité pour être soigné(e) en Espagne à charge de la Belgique.","Inscrivez-vous au registre consulaire de l'ambassade ou d'un consulat belge en Espagne (passeport, élections, documents).","Impôts : l'année du départ, déclarez vos revenus en Belgique jusqu'à la date de départ. Certains revenus belges, comme les pensions du secteur public, peuvent rester imposables en Belgique selon la convention."],
    ["Report your departure to your municipality before leaving: you will receive a change-of-residence certificate (model 8).","Pensioners: ask your health fund (mutualité/ziekenfonds) for the S1 form to be treated in Spain at Belgium's expense.","Register with the consular register of the Belgian embassy or a consulate in Spain (passport, elections, documents).","Taxes: in the year you leave, declare your income in Belgium up to your departure date. Some Belgian income, such as public-sector pensions, may remain taxable in Belgium under the treaty."],
    ["Declara tu salida en tu municipio antes de irte: recibirás un certificado de cambio de residencia (modelo 8).","Pensionistas: pide el formulario S1 a tu mutualidad para recibir asistencia en España a cargo de Bélgica.","Inscríbete en el registro consular de la embajada o de un consulado belga en España (pasaporte, elecciones, documentos).","Impuestos: el año de la salida declaras en Bélgica tus rentas hasta la fecha de partida. Algunas rentas belgas, como las pensiones públicas, pueden seguir tributando en Bélgica según el convenio."],
    ["Melde deinen Wegzug vor der Abreise bei deiner Gemeinde: Du erhältst eine Bescheinigung über den Wohnsitzwechsel (Modell 8).","Rentner: Beantrage bei deiner Krankenkasse (Mutualität) das Formular S1, um in Spanien auf Kosten Belgiens behandelt zu werden.","Trage dich im Konsularregister der belgischen Botschaft oder eines Konsulats in Spanien ein (Pass, Wahlen, Dokumente).","Steuern: Im Jahr des Wegzugs erklärst du dein Einkommen in Belgien bis zum Wegzugsdatum. Manche belgischen Einkünfte, etwa Beamtenpensionen, können laut Abkommen in Belgien steuerpflichtig bleiben."],
    ["Meld je vertrek bij je gemeente vóór je vertrekt: je krijgt een attest van adreswijziging (model 8).","Gepensioneerden: vraag bij je ziekenfonds het formulier S1 aan om in Spanje verzorgd te worden op kosten van België.","Schrijf je in het consulaire register in bij de Belgische ambassade of een consulaat in Spanje (paspoort, verkiezingen, documenten).","Belastingen: in het jaar van vertrek geef je je inkomsten in België aan tot de vertrekdatum. Sommige Belgische inkomsten, zoals overheidspensioenen, kunnen volgens het verdrag in België belastbaar blijven."]
   ]) },
 { code:"FR", links:[["Service-Public (vivre à l'étranger)","https://www.service-public.fr/"],["Impôts","https://www.impots.gouv.fr/"],["Ameli","https://www.ameli.fr/"]],
   p:tr([
    ["Pas de radiation en mairie : signalez votre nouvelle adresse aux impôts, à votre caisse de retraite, à votre banque et à vos assurances.","Retraités : demandez le formulaire S1 à votre caisse d'assurance maladie pour être soigné(e) en Espagne à charge de la France.","L'inscription au registre des Français établis hors de France (consulat) est facultative mais conseillée.","Impôts : l'année du départ, déclarez vos revenus en indiquant la date de départ. Certains revenus de source française restent imposables en France. Chômage : le formulaire U2 permet de toucher vos allocations pendant votre recherche en Espagne, pour une durée limitée."],
    ["No deregistration at the town hall: give your new address to the tax office, your pension fund, your bank and your insurers.","Pensioners: ask your health insurance fund for the S1 form to be treated in Spain at France's expense.","Registering with the register of French nationals abroad (consulate) is optional but recommended.","Taxes: in the year you leave, declare your income and state your departure date. Some French-source income stays taxable in France. Unemployment: form U2 lets you keep benefits for a limited time while job hunting in Spain."],
    ["No hay baja en el ayuntamiento: comunica tu nueva dirección a Hacienda, a tu caja de pensiones, a tu banco y a tus seguros.","Jubilados: pide el formulario S1 a tu caja del seguro de enfermedad para recibir asistencia en España a cargo de Francia.","La inscripción en el registro de franceses en el extranjero (consulado) es opcional pero recomendable.","Impuestos: el año de salida declaras tus rentas indicando la fecha de partida. Algunas rentas de fuente francesa siguen tributando en Francia. Desempleo: el formulario U2 permite cobrar la prestación durante un tiempo limitado mientras buscas trabajo en España."],
    ["Keine Abmeldung im Rathaus: Teile Finanzamt, Rentenkasse, Bank und Versicherungen deine neue Adresse mit.","Rentner: Beantrage bei deiner Krankenkasse das Formular S1, um in Spanien auf Kosten Frankreichs behandelt zu werden.","Die Eintragung ins Register der Franzosen im Ausland (Konsulat) ist freiwillig, aber empfehlenswert.","Steuern: Im Jahr des Wegzugs gibst du dein Einkommen mit dem Wegzugsdatum an. Manche Einkünfte aus Frankreich bleiben dort steuerpflichtig. Arbeitslosigkeit: Mit dem Formular U2 kannst du das Arbeitslosengeld für begrenzte Zeit bei der Jobsuche in Spanien behalten."],
    ["Geen uitschrijving bij het gemeentehuis: geef je nieuwe adres door aan de belastingdienst, je pensioenkas, je bank en je verzekeraars.","Gepensioneerden: vraag bij je ziekenfonds het formulier S1 aan om in Spanje verzorgd te worden op kosten van Frankrijk.","Inschrijving in het register van Fransen in het buitenland (consulaat) is optioneel maar aangeraden.","Belastingen: in het jaar van vertrek geef je je inkomsten aan met de vertrekdatum. Sommige inkomsten uit Frankrijk blijven daar belastbaar. Werkloosheid: met formulier U2 behoud je je uitkering een beperkte tijd terwijl je in Spanje werk zoekt."]
   ]) },
 { code:"NL", links:[["Rijksoverheid (emigreren)","https://www.rijksoverheid.nl/"],["SVB","https://www.svb.nl/"],["Belastingdienst","https://www.belastingdienst.nl/"]],
   p:tr([
    ["Désinscrivez-vous de votre commune (BRP) si vous partez plus de 8 mois : votre assurance santé néerlandaise prend alors fin.","Pensionnés : la couverture santé en Espagne passe en général par le formulaire S1, via le CAK (verdragsregeling).","AOW : communiquez votre nouvelle adresse à la SVB. Vous ne cotisez plus pour l'AOW en vivant à l'étranger, une assurance volontaire est possible.","Impôts : l'année de l'émigration, remplissez la déclaration « M » de la Belastingdienst."],
    ["Deregister from your municipality (BRP) if you leave for more than 8 months: your Dutch health insurance then ends.","Pensioners: healthcare in Spain usually goes through the S1 form, via the CAK (treaty arrangement).","AOW: give your new address to the SVB. You stop building AOW while living abroad; voluntary insurance is possible.","Taxes: in the year you emigrate, file the Belastingdienst's “M” return."],
    ["Date de baja en tu municipio (BRP) si te vas más de 8 meses: tu seguro de salud neerlandés termina entonces.","Pensionistas: la cobertura sanitaria en España suele pasar por el formulario S1, a través del CAK (verdragsregeling).","AOW: comunica tu nueva dirección a la SVB. Dejas de cotizar para la AOW al vivir fuera; existe un seguro voluntario.","Impuestos: el año de emigración, presenta la declaración «M» de la Belastingdienst."],
    ["Melde dich bei deiner Gemeinde ab (BRP), wenn du länger als 8 Monate weg bist: Deine niederländische Krankenversicherung endet dann.","Rentner: Die Versorgung in Spanien läuft meist über das Formular S1, über das CAK (verdragsregeling).","AOW: Teile der SVB deine neue Adresse mit. Im Ausland baust du keine AOW mehr auf, eine freiwillige Versicherung ist möglich.","Steuern: Reiche im Auswanderungsjahr die „M“-Erklärung der Belastingdienst ein."],
    ["Schrijf je uit bij je gemeente (BRP) als je langer dan 8 maanden vertrekt: je Nederlandse zorgverzekering stopt dan.","Gepensioneerden: zorg in Spanje loopt meestal via formulier S1, via het CAK (verdragsregeling).","AOW: geef je nieuwe adres door aan de SVB. In het buitenland bouw je geen AOW meer op; vrijwillig verzekeren kan.","Belastingen: vul in het jaar van emigratie de M-aangifte van de Belastingdienst in."]
   ]) },
 { code:"DE", links:[["Auswärtiges Amt","https://www.auswaertiges-amt.de/"],["Deutsche Rentenversicherung","https://www.deutsche-rentenversicherung.de/"]],
   p:tr([
    ["Faites votre Abmeldung au Bürgeramt dans les deux semaines suivant le départ.","Retraités : demandez le formulaire S1 à votre Krankenkasse pour être soigné(e) en Espagne.","Deutsche Rentenversicherung : communiquez votre nouvelle adresse et votre compte bancaire ; la pension est versée dans l'UE.","Impôts : l'assujettissement illimité prend fin avec le départ, mais les pensions allemandes peuvent rester imposables en Allemagne (centre des impôts de Neubrandenburg pour les retraités à l'étranger). Chômage : formulaire U2 auprès de l'Agentur für Arbeit."],
    ["Do your Abmeldung at the Bürgeramt within two weeks of leaving.","Pensioners: ask your Krankenkasse for the S1 form to be treated in Spain.","Deutsche Rentenversicherung: give your new address and bank account; the pension is paid anywhere in the EU.","Taxes: unlimited tax liability ends when you leave, but German pensions may remain taxable in Germany (Neubrandenburg tax office for pensioners abroad). Unemployment: form U2 from the Agentur für Arbeit."],
    ["Haz la Abmeldung en el Bürgeramt en las dos semanas siguientes a la salida.","Jubilados: pide el formulario S1 a tu Krankenkasse para recibir asistencia en España.","Deutsche Rentenversicherung: comunica tu nueva dirección y cuenta bancaria; la pensión se paga en toda la UE.","Impuestos: la obligación ilimitada termina con la salida, pero las pensiones alemanas pueden seguir tributando en Alemania (oficina de Neubrandenburg para jubilados en el extranjero). Desempleo: formulario U2 en la Agentur für Arbeit."],
    ["Melde dich innerhalb von zwei Wochen nach dem Auszug beim Bürgeramt ab.","Rentner: Beantrage bei deiner Krankenkasse das Formular S1 für die Behandlung in Spanien.","Deutsche Rentenversicherung: Neue Adresse und Bankverbindung melden; die Rente wird überall in der EU gezahlt.","Steuern: Die unbeschränkte Steuerpflicht endet mit dem Wegzug, deutsche Renten können aber in Deutschland steuerpflichtig bleiben (Finanzamt Neubrandenburg für Rentner im Ausland). Arbeitslosigkeit: Formular U2 bei der Agentur für Arbeit."],
    ["Meld je binnen twee weken na vertrek af bij het Bürgeramt.","Gepensioneerden: vraag bij je Krankenkasse het formulier S1 aan voor zorg in Spanje.","Deutsche Rentenversicherung: geef je nieuwe adres en bankrekening door; het pensioen wordt overal in de EU uitbetaald.","Belastingen: de onbeperkte belastingplicht eindigt met het vertrek, maar Duitse pensioenen kunnen in Duitsland belastbaar blijven (belastingkantoor Neubrandenburg voor gepensioneerden in het buitenland). Werkloosheid: formulier U2 bij de Agentur für Arbeit."]
   ]) },
 { code:"GB", links:[["GOV.UK — Living in Spain","https://www.gov.uk/guidance/living-in-spain"],["GOV.UK","https://www.gov.uk/"]],
   p:tr([
    ["Depuis le Brexit, un visa est nécessaire pour vivre en Espagne, sauf pour les personnes déjà résidentes avant 2021 (accord de retrait, carte TIE).","Informez HMRC de votre départ (formulaire P85) et l'International Pension Centre de votre nouvelle adresse : la State Pension peut être versée en Espagne et y est revalorisée.","Les retraités britanniques peuvent obtenir un S1 pour être soignés en Espagne (NHS Overseas Healthcare Services).","Permis : un accord Royaume-Uni–Espagne permet l'échange du permis britannique, à faire dans les 6 mois suivant l'obtention de la résidence."],
    ["Since Brexit you need a visa to live in Spain, unless you were already resident before 2021 (Withdrawal Agreement, TIE card).","Tell HMRC you are leaving (form P85) and the International Pension Centre your new address: the State Pension can be paid in Spain and is uprated there.","UK pensioners can get an S1 for healthcare in Spain (NHS Overseas Healthcare Services).","Licence: a UK–Spain agreement allows you to exchange your UK licence, within 6 months of becoming resident."],
    ["Desde el Brexit se necesita visado para vivir en España, salvo quienes ya residían antes de 2021 (Acuerdo de Retirada, TIE).","Informa a HMRC de tu salida (formulario P85) y al International Pension Centre de tu nueva dirección: la State Pension se puede cobrar en España y se revaloriza.","Los pensionistas británicos pueden obtener un S1 para recibir asistencia en España (NHS Overseas Healthcare Services).","Permiso: un acuerdo Reino Unido–España permite canjear el permiso británico en los 6 meses siguientes a obtener la residencia."],
    ["Seit dem Brexit brauchst du ein Visum für Spanien, außer du warst schon vor 2021 ansässig (Austrittsabkommen, TIE).","Informiere HMRC über den Wegzug (Formular P85) und das International Pension Centre über die neue Adresse: Die State Pension wird in Spanien gezahlt und dort angepasst.","Britische Rentner können ein S1 für die Versorgung in Spanien erhalten (NHS Overseas Healthcare Services).","Führerschein: Ein Abkommen zwischen UK und Spanien erlaubt den Umtausch innerhalb von 6 Monaten nach Erhalt des Wohnsitzes."],
    ["Sinds de Brexit heb je een visum nodig om in Spanje te wonen, tenzij je er al vóór 2021 woonde (terugtrekkingsakkoord, TIE).","Meld je vertrek aan HMRC (formulier P85) en je nieuwe adres aan het International Pension Centre: de State Pension kan in Spanje uitbetaald worden en wordt er geïndexeerd.","Britse gepensioneerden kunnen een S1 krijgen voor zorg in Spanje (NHS Overseas Healthcare Services).","Rijbewijs: een akkoord tussen het VK en Spanje laat omwisseling toe binnen 6 maanden na het verkrijgen van de verblijfsvergunning."]
   ]) }
];

