    <nav class="tabs big-tabs">${[["sale", "mk_tab_sale", "🏷"], ["gift", "mk_tab_gift", "🎁"], ["mine", "mk_tab_mine", "📦"]].filter(x => x[0] !== "mine" || H.me).map(([k, l, ic]) => `<a class="tabbtn" href="#/vente?t=${k}" ${tab === k ? 'aria-current="page"' : ""}>${ic} ${esc(t(l))}</a>`).join("")}</nav>
