// ================= RÉSEAUX SOCIAUX DES MEMBRES =================
const NETS = [
  ["instagram", "Instagram", h => "https://www.instagram.com/" + h], ["facebook", "Facebook", h => "https://www.facebook.com/" + h],
  ["tiktok", "TikTok", h => "https://www.tiktok.com/@" + h], ["linkedin", "LinkedIn", h => "https://www.linkedin.com/in/" + h],
  ["youtube", "YouTube", h => "https://www.youtube.com/@" + h], ["whatsapp", "WhatsApp", h => "https://wa.me/" + h.replace(/[^\d]/g, "")],
  ["website", "Site web", h => "https://" + h]
];
function normSocial(key, v) {
  v = String(v || "").trim(); if (!v) return "";
  if (/^https?:\/\//i.test(v)) return v.slice(0, 250);
  const n = NETS.find(x => x[0] === key); if (!n) return "";
  return n[2](v.replace(/^@/, "").replace(/^www\./, "")).slice(0, 250);
}
window.HV_SOCIAL_FIELDS = social => `<fieldset><legend>${esc(t("sn_title"))}</legend><p class="small muted">${esc(t("sn_help"))}</p>
  <div class="grid">${NETS.map(([k, n]) => `<label>${esc(k === "website" ? t("lp_site") : n)}<input name="soc_${k}" maxlength="250" value="${esc((social || {})[k] || "")}" placeholder="${k === "whatsapp" ? "+34 600 000 000" : k === "website" ? "monsite.com" : "@pseudo"}"></label>`).join("")}</div></fieldset>`;
window.HV_READ_SOCIAL = f => { const o = {}; NETS.forEach(([k]) => { const v = normSocial(k, f.get("soc_" + k)); if (v) o[k] = v; }); return o; };
const ICON = { instagram: "IG", facebook: "f", tiktok: "♪", linkedin: "in", youtube: "▶", whatsapp: "✆", website: "🌐" };
H.socialButtons = social => {
  const list = NETS.filter(([k]) => social && social[k] && /^https?:\/\//i.test(social[k]));
  return list.length ? `<div class="member-social">${list.map(([k, n]) => `<a class="ms-btn ms-${k}" href="${esc(social[k])}" target="_blank" rel="noopener nofollow" title="${esc(k === "website" ? t("lp_site") : n)}"><span>${ICON[k]}</span></a>`).join("")}</div>` : "";
};
(window.HV_HOOKS = window.HV_HOOKS || {}).profile = (window.HV_HOOKS.profile || []).concat([p => {
  const html = H.socialButtons(p.social); if (!html) return;
  const h1 = $(".profile-head h1", view) || $("h1", view); const target = h1 ? h1.parentElement : $(".page", view);
  if (target && !$(".member-social", target)) target.insertAdjacentHTML("beforeend", html);
}]);

