window.HV_OAUTH = signup => {
  const g = C.AUTH_GOOGLE, f = C.AUTH_FACEBOOK; if (!g && !f) return "";
  return `<div class="oauth"><p class="oauth-or"><span>${esc(t("oa_or"))}</span></p>
    ${g ? `<button type="button" class="btn oauth-btn g" data-oauth="google"><span class="oa-ic">G</span> ${esc(t("oa_google"))}</button>` : ""}
    ${f ? `<button type="button" class="btn oauth-btn fb" data-oauth="facebook"><span class="oa-ic">f</span> ${esc(t("oa_facebook"))}</button>` : ""}
    ${signup ? `<p class="small muted">${esc(t("oa_note"))}</p>` : ""}</div>`;
};
document.addEventListener("click", async e => {
  const b = e.target.closest("[data-oauth]"); if (!b || !H.sb) return;
  b.disabled = true;
  const { error } = await H.sb.auth.signInWithOAuth({ provider: b.dataset.oauth, options: { redirectTo: location.origin + location.pathname } });
  if (error) { b.disabled = false; toast(errMsg(error)); }
});
function oauthReturn() {
  const h = new URLSearchParams(location.hash.slice(1));
  if (h.get("error")) toast(t("oa_error") + " " + (h.get("error_description") || h.get("error")));
  history.replaceState(null, "", location.pathname + location.search + "#/");
  window.dispatchEvent(new HashChangeEvent("hashchange"));
}

